import itertools
def task_func(d):
    lists = list(d.values())
    if not lists:
        return {}
    counts = Counter(itertools.chain.from_iterable(lists))
    common = set(lists[0])
    for lst in lists[1:]:
        common &= set(lst)
    return {k: v for k, v in counts.items() if k in common}

